import React, { PropsWithChildren } from 'react';
import { isElement } from 'react-is';

//#region Typings
/** Accepted properties for the Select DisplayValue */
export type SelectV2DisplayValueProps = PropsWithChildren<unknown>;
//#endregion

/**
 * Typeguard function that will check if a React.Node is a SelectV2.DisplayValue
 * @internal
 */
export function _isSelectV2DisplayValueElement(
  child: React.ReactNode,
): child is React.ReactElement<SelectV2DisplayValueProps> {
  if (isElement(child) && child.type === SelectV2DisplayValue) {
    return true;
  }
  return false;
}

/**
 * `SelectV2.DisplayValue` defines a custom display within the Trigger. A SelectV2.DisplayValue component
 * is only valid within a SelectV2.Trigger and accepts the following slots
 *
 * - SelectV2.Prefix
 * - Freeform JSX content
 *
 * @example
 * ```tsx
 * <SelectV2.DisplayValue>
 *   <SelectV2.Prefix>
 *     <WhatsNewIcon />
 *   </SelectV2.Prefix>
 *   Selected color:
 *   <Flex
 *     style={{ background: value }}
 *     width={'1rem'}
 *     height={'1rem'}
 *   />
 * </SelectV2.DisplayValue>
 * ```
 */
export function SelectV2DisplayValue(props: SelectV2DisplayValueProps) {
  return null;
}

SelectV2DisplayValue.displayName = 'SelectV2.DisplayValue';
